    def __init__(self, inner):
        self._inner = inner
    def get(self, key):
        if not key:
            raise ValueError("key required")
        return self._inner.get(key)
    def put(self, key, value):
        if not key:
            raise ValueError("key required")
        return self._inner.put(key, value)

